const char* oidc_util_hdr_in_x_forwarded_host_get(const request_rec *r) { /* <=== oidc_util_hdr_in_x_forwarded_host_get */ 
	return oidc_util_hdr_in_get_left_most_only(r,
			OIDC_HTTP_HDR_X_FORWARDED_HOST, OIDC_STR_COMMA OIDC_STR_SPACE);
