char* oidc_util_get_full_path(apr_pool_t *pool, const char *abs_or_rel_filename) { /* <=== oidc_util_get_full_path */ 
	return (abs_or_rel_filename) ?
			ap_server_root_relative(pool, abs_or_rel_filename) : NULL;
